    this.currentSteeringAngle = 15;
    this.currentSpeed = 0;
    this.calibrationDoneReceived = false;
    this.pendingMeasurementSubmission = null;
    this.isCalibrationRunInProgress = false;
    this.previousKlValue = "0";
    this.previousStepIndex = 0;
    this.previousSubstepId = null;
    this.leftCompleted = false;
    this.rightCompleted = false;
    this.backwardCompleted = false;
    this.testRunCompleted = false;
    this.calibrationSavedSuccessfully = false;
    this.savedCalibrationMeasurements = [];
    this.selectedSavedMeasurementId = "";
    this.saveMeasurementName = "";
    this.calibrationMeasurementsMessage = null;
    this.calibrationMeasurementsMessageType = null;
